using System.Windows; using System.Windows.Controls; using DocumentManagement.Services;
namespace DocumentManagement.Views.Updates; public partial class UpdateDownloadingView:UserControl { public event EventHandler? HideRequested; private string _version=""; public UpdateDownloadingView(){InitializeComponent();} public void Configure(string version,string current,AppUpdateProgress p){_version=version;TitleText.Text=$"Đang cập nhật phiên bản {version}";Update(p);} public void Update(AppUpdateProgress p){ProgressBar.IsIndeterminate=!p.Percent.HasValue;if(p.Percent.HasValue)ProgressBar.Value=Math.Clamp(p.Percent.Value,0,100);DetailsText.Text=p.TotalBytes is > 0 && p.DownloadedBytes.HasValue?$"{p.DownloadedBytes.Value/1024d/1024d:0.0} / {p.TotalBytes.Value/1024d/1024d:0.0} MB · {p.Percent ?? 0:0}%":p.Message;} private void Hide_Click(object s,RoutedEventArgs e)=>HideRequested?.Invoke(this,EventArgs.Empty);}
